update_rule.pseudocode:
actions = 0; checks = 0; compliant_checks = 0
for each person i:
  visits = []
  if assigned workplace and Bernoulli(workplace_attendance_rate): visits.append(workplace)
  if Bernoulli(public_venue_visit_rate): visits.append(random_public_venue)
  for loc in visits:
    requires = Location[loc].policy_requires_mask
    strict = Location[loc].enforcement_strictness * location_enforcement_strictness_mean
    checks += 1 if requires else 0
    if requires:
      wear_at_entry = Person[i].mask_use_state
      if not wear_at_entry and Person[i].mask_inventory > 0:
        # opportunistic compliance
        wear_at_entry = Bernoulli(strict * (0.5 + 0.5*policy_state.mandate_active))
        if wear_at_entry: Person[i].mask_inventory -= 1
      if wear_at_entry:
        compliant_checks += 1
      else:
        # enforcement action
        actions += 1
        if Bernoulli(penalty_warning_probability) == 0:
          # fine issued
          Person[i].compliance_propensity = clip(Person[i].compliance_propensity + 0.1, 0, 1)
        else:
          Person[i].compliance_propensity = clip(Person[i].compliance_propensity + 0.05, 0, 1)
  record observations.by_person_context[i] = fraction of others wearing at visited locations (for Decision module)
compliance_rate = compliant_checks / max(1, checks)
output daily.enforcement_actions = actions and observable.compliance_rate_mandate_daily = compliance_rate
